 {Synth s;bs_sauce_config sauce{},sauceAfter{};bs_default_sauce(&sauce);CHECK(bs_set_sauce(s.p,&sauce));bs_modulation_config_v3 mod{},modAfter{};bs_default_modulation_v3(&mod);CHECK(bs_set_modulation_v3(s.p,&mod));auto notes=generators(BS_NOTE_ARP);bs_notes_config notesAfter{};CHECK(bs_set_notes(s.p,&notes));bs_patch patch{},after{};CHECK(bs_get_patch(s.p,&patch));auto badSauce=sauce;badSauce.count=17;CHECK(!bs_set_sauce(s.p,&badSauce));auto badMod=mod;badMod.sources[0].routes[0].depth=std::numeric_limits<float>::quiet_NaN();CHECK(!bs_set_modulation_v3(s.p,&badMod));auto badNotes=notes;badNotes.blocks[1].id=badNotes.blocks[0].id;CHECK(!bs_set_notes(s.p,&badNotes));CHECK(bs_get_sauce(s.p,&sauceAfter)&&bs_get_modulation_v3(s.p,&modAfter)&&bs_get_notes(s.p,&notesAfter)&&bs_get_patch(s.p,&after));CHECK(std::memcmp(&sauce,&sauceAfter,sizeof sauce)==0&&std::memcmp(&mod,&modAfter,sizeof mod)==0&&std::memcmp(&notes,&notesAfter,sizeof notes)==0&&std::memcmp(&patch,&after,sizeof patch)==0);}
 CHECK(allocations==0);std::puts("PASS all three configuration APIs reject atomically without altering tone/rack state and render allocates nothing");
